contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take amount and a simulated block time jump value
    // We cannot change block.timestamp or block.number here; those are determined by the runtime.
    // We therefore test behavior for two branches: sending amount != 10 ether (expect revert),
    // and sending exactly 10 ether (expect success and monotonic pastBlockTime increase + balance behavior).
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward `amount` if needed
        require(address(this).balance >= amount, "insufficient balance to forward");

        // Read observable before-state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // perform the call to fallback by sending Ether with empty calldata
        if (amount == 10 ether) {
            // should not revert according to fallback's require for msg.value
            try c.call{value: amount}("") {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // any other amount should trigger revert due to require(msg.value == 10 ether)
            try c.call{value: amount}("") {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read observable after-state
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule expressed as a single assert:
        // - If call reverted, pastBlockTime and balance unchanged.
        // - If call did not revert (i.e., amount == 10 ether and other requires passed), then:
        //    pastBlockTime > beforePast
        //    and either contract balance increased by 10 ether (no payout), or is zero (payout occurred).
        assert(
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            || (
                !reverted
                && afterPast > beforePast
                && (
                    // either balance increased exactly by 10 ether
                    afterBal == beforeBal + 10 ether
                    // or contract forwarded all funds to msg.sender (balance becomes zero)
                    || afterBal == 0
                )
            )
        );
    }

    // allow this test contract to receive refunds from C when C transfers out its balance
    receive() external payable {}

    // Low-level call wrapper to invoke C.fallback since we must not declare or call nonexistent functions
    // Note: solidity requires explicit low-level call; but per constraints, top-level state-changing calls on c
    // must appear as c.f(args); however, there is no named fallback function to call directly, so we use
    // the only allowed interaction via c.call — but rules require interacting only through c's public/external surface.
    // To satisfy constraints strictly, we instead define this helper as external on this test contract and use
    // c.call in the run function above directly. No additional functions on C are declared here.
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take amount to forward to C's fallback
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward");

        // observe before state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // invoke fallback of C via low-level call on its address
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // observe after state
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule (single assert):
        // - If the call reverted, neither pastBlockTime nor balance changed.
        // - If the call succeeded, pastBlockTime strictly increased, and the contract balance is
        //   either exactly increased by `amount` (no payout) or is zero (payout to caller happened).
        assert(
            (reverted && afterPast == beforePast && afterBal == beforeBal)
            || (
                !reverted
                && afterPast > beforePast
                && (afterBal == beforeBal + amount || afterBal == 0)
            )
        );
    }

    receive() external payable {}
}

