contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send and a simulated block timestamp/number are not controllable here,
    // so the only input we control is the Ether amount. We must require the caller funds this contract
    // so it can forward the Ether to c.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "need funds to forward");
        // read observable before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        // Make the call to fallback by sending Ether to c. This may revert if amount != 10 ether or timestamp conditions fail.
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // General rule: If the call with exactly 10 ether succeeded, then pastBlockTime was updated to block.timestamp + 1
        // and strictly increased relative to before; furthermore, if the block number is not divisible by 15 then the contract retained the 10 ether
        // (its balance increased by exactly amount) and no funds were sent back to this test contract.
        // We express "call succeeded with exactly 10 ether" as (!reverted && amount == 10 ether).
        // Use block.number % 15 != 0 to characterize the transfer behavior.
        assert(
            !( !reverted && amount == 10 ether ) ||
            ( afterPast == block.timestamp + 1 && afterPast > beforePast &&
              ( (block.number % 15 != 0 && afterBalance == beforeBalance + amount) || (block.number % 15 == 0 && afterBalance == 0) )
            )
        );
    }

    // Allow receiving refunded Ether if any (though the contract's fallback transfers only to msg.sender when block.number%15==0)
    receive() external payable {}
}

