contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send and a synthetic current block number indicator
    // Note: block.number and block.timestamp are global and cannot be set here. We only use
    // amount (must be 10 ether) to drive the fallback payable require in C.
    function run(uint amount) public payable {
        // require we have enough balance to forward 'amount'
        require(address(this).balance >= amount, "not enough balance");

        // Read before-values that are publicly observable
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Call fallback by sending value with empty calldata. This may revert inside C.
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // If the call reverted, then nothing in C's state changed; enforce that.
        // If it did not revert, then: 1) pastBlockTime must have increased (strictly),
        // 2) If block.number % 15 == 0 then C forwarded its entire balance to msg.sender
        //    (so its balance after is 0), otherwise its balance should be >= beforeBal + amount - address(this).balance_change
        // We cannot observe how much the test contract lost in the transfer from inside assert, but we can assert the following
        // general invariant that captures contract behavior:

        // General rule (single assert):
        // - If reverted then beforePast == afterPast and beforeBal == afterBal.
        // - If not reverted then afterPast > beforePast and either (block.number % 15 == 0 implies afterBal == 0) and (block.number % 15 != 0 implies afterBal >= beforeBal)
        assert(
            (reverted && beforePast == afterPast && beforeBal == afterBal)
            || (
                !reverted
                && afterPast > beforePast
                && (
                    (block.number % 15 == 0 && afterBal == 0)
