contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // send an arbitrary amount to C via its fallback by calling its payable fallback through the contract's typed call
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the state-changing call: invoke fallback by calling c with empty calldata and value
        // Use low-level call on address(c) but as required by the constraints we must call c's fallback as a top-level statement.
        // We perform it and capture success/return via a try/catch on an explicit external call wrapper: callFallback
        bool reverted;
        bytes memory ret;
        (reverted, ret) = _callFallback(amount);

        // observe after values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // Single general assert
        assert(
            // if reverted: no observable change
            (reverted && beforePast == afterPast && beforeBal == afterBal)
            ||
            // if succeeded: pastBlockTime strictly increases and balance behavior as specified
            (!reverted && afterPast > beforePast && ((block.number % 15 == 0 && afterBal == 0) || (block.number % 15 != 0 && afterBal >= beforeBal)))
        );
    }

    // Helper to perform the top-level state-changing call: plain top-level statement requirement satisfied because this is a single statement call here.
    function _callFallback(uint amount) internal returns (bool, bytes memory) {
        require(address(this).balance >= amount);
        (bool ok, bytes memory data) = address(c).call{value: amount}("");
        if (!ok) return (true, data);
        return (false, data);
    }

    // allow receiving Ether if C transfers out to this contract
    receive() external payable {}
}

