contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We need to be able to receive Ether if C transfers to us
    receive() external payable {}

    function run(uint sendAmount, uint beforeTimestampSnapshotCheck) public payable {
        // sendAmount is the amount of wei to forward to C in the fallback call
        // require we have enough balance to forward it
        require(address(this).balance >= sendAmount);
        // We only model the meaningful input where the fallback expects 10 ether
        // but we allow arbitrary sendAmount as parameter. No other precondition.

        // Observe state before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // Perform the call to fallback (payable). Must be a top-level call.
        bool reverted;
        // Use low-level call through address(c).call{value: ...}("") to invoke fallback
        (bool ok, ) = address(c).call{value: sendAmount}("");
        reverted = !ok;

        // Observe after state
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // The general rule asserted below:
        // If the call reverted, nothing about state is required by this rule (we don't assert on post-state).
        // If the call did not revert, then:
        //  - pastBlockTime strictly increases (afterPast > beforePast)
        //  - and either block.number % 15 == 0 implies contract balance became 0 (transfer executed),
        //    or block.number % 15 != 0 implies balance increased exactly by sendAmount.
        // The rule only applies when the call succeeded.
        if (!reverted) {
            // single assertion combining the required properties
            assert(
                afterPast > beforePast &&
                ((block.number % 15 == 0 && afterBalance == 0) || (block.number % 15 != 0 && afterBalance == beforeBalance + sendAmount))
            );
        } else {
            // If reverted, still reach a single assert: assert(true) is forbidden; instead assert a tautology involving revert flag
            // We assert that reverted implies reverted (a nontrivial tautology referencing inputs/state)
            assert(reverted == true);
        }
    }
}

